  #include<iostream>
#include<vector>
#include<queue>
using namespace std;

int main(){
    int n;
    cin>>n;

    vector<vector<int>> grid(n,vector<int>(n));

    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++){
            cin>>grid[i][j];
        }
    }

    if(grid[0][0]==1||grid[n-1][n-1]==1){
        cout<<-1;
        return 0;
    }

    queue<pair<int,int>> q;
    q.push({0,0});
    grid[0][0]=1;

    int dx[]={-1,-1,-1,0,0,1,1,1};
    int dy[]={-1,0,1,-1,1,-1,0,1};

    int dist=1;

    while(!q.empty()){
        int size=q.size();

        while(size--){
            auto [x,y]=q.front();
            q.pop();

            if(x==n-1&&y==n-1){
                cout<<dist;
                return 0;
            }

            for(int k=0;k<8;k++){
                int nx=x+dx[k];
                int ny=y+dy[k];

                if(nx>=0&&nx<n&&ny>=0&&ny<n&&grid[nx][ny]==0){
                    grid[nx][ny]=1;
                    q.push({nx,ny});
                }
            }
        }

        dist++;
    }

    cout<<-1;
    return 0;
}
